    Desc = "Summon_131639_Desc|每<SummonOrange:5>次唤醒必出SR级或以上对象",
    ListBackgroundImage = "UIResources/AtlasSource/UI_Summon_Image/UI_Summon_D_Tab_Career_87.png",
