    RateListTextSSR = "Summon_139915_RateListTextSSR|SSR物品基础出率：3.03%<color=#A3A6AB>（含保底综合出率：5.02%）</color>",
    RateListTextSR = "Summon_139915_RateListTextSR|SR物品基础出率：15.85%<color=#A3A6AB>（含保底综合出率：25.00%）</color>",
    RateListTextR = "Summon_139915_RateListTextR|R物品基础出率：81.12%<color=#A3A6AB>（含保底综合出率：69.98%）</color>"
  },
