    BackgroundImage = "UIResources/UIBigImages/UI_Large/UI_Summon_D_ImgPanel_BG2.png",
    VXPrefab = "UI/UI_Summon/UI_Summon_Prefab/UI_Summon_VX_Tulu.prefab",
